    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xF439A204A5917CBFULL + 0xCB91F8AE3EBDFFD1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0xEFF81324C28E66BDULL + 0xFF04FC8872831819ULL);
