            //
            aOrbiterH = (((aWandererK + RotL64(aPrevious, 11U)) + 0x52AC4826388EF225ULL) + aOrbiterAssignSaltB[(((255U - aIndex) + 213U)) & S_SALT1]) + aNonceWordL;
