            aOrbiterF = (aWandererD + RotL64(aCross, 23U)) + 0xED02F70C73F8E6F6ULL;
            aOrbiterC = ((aWandererB + RotL64(aScatter, 60U)) + RotL64(aCarry, 3U)) + 0x17E12117E63BF717ULL;
            aOrbiterG = (aWandererG + RotL64(aCross, 5U)) + 0x99F9AE1A235125ACULL;
            aOrbiterI = ((((aWandererJ + RotL64(aPrevious, 35U)) + RotL64(aCarry, 47U)) + 0x20DE558FB315F41CULL) + aOrbiterAssignSaltA[((aIndex + 234U)) & S_SALT1]) + aNonceWordC;
