            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xA6D7374A17416D67ULL) + aNonceWordK;
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0xA0F17F4D5CDAD34BULL) ^ aOrbiterUpdateSaltF[(((255U - aIndex) + 183U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xE0FBBE763D6B6BAFULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x2DAB0C74907CF3F0ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x4484B2AD5690C397ULL) ^ aNonceWordJ;
