            aOrbiterE = RotL64((aOrbiterE * 0x6363BFA821FA377FULL), 19U);
            //
            aIngress = RotL64(aOrbiterC, 51U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterG, 57U) ^ aOrbiterE);
