            aIngress ^= (RotL64(aCrystalLaneA[((aIndex + 11744U)) & S_BLOCK1], 27U) ^ RotL64(aCelestialLaneA[((S_BLOCK1 - aIndex + 8982U)) & S_BLOCK1], 40U));
            aIngress = TwistMix64::DiffuseC(((aIngress ^ aDomainWordIngress) ^ aNonceWordO));
            //
            aCross = (RotL64(aVaporLaneA[((S_BLOCK1 - aIndex + 9113U)) & S_BLOCK1], 41U) ^ RotL64(aVaporLaneB[((S_BLOCK1 - aIndex + 12767U)) & S_BLOCK1], 11U));
            aCross ^= (RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 8825U)) & S_BLOCK1], 3U) ^ RotL64(aAetherLaneD[((aIndex + 10077U)) & S_BLOCK1], 52U));
            aCross = TwistMix64::DiffuseC(((aCross ^ aDomainWordCross) ^ aNonceWordI));
            //
            aScatter = (RotL64(aCarry, 28U) + RotL64(aPrevious, 11U)) ^ (RotL64(aIngress, 57U) + RotL64(aCross, 41U));
            aScatter = TwistMix64::DiffuseC(((aScatter ^ aDomainWordScatter) ^ aNonceWordP));
            //
            aOrbiterC = ((aWandererK + RotL64(aScatter, 13U)) + RotL64(aCarry, 29U)) + 0x46C27967B565DE65ULL;
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 21U)) + 0x0463698C82B2352DULL) + aNonceWordK;
            aOrbiterB = ((aWandererB + RotL64(aCross, 50U)) + 0xAE0DF25DC3213DE9ULL) + aOrbiterAssignSaltE[(((255U - aIndex) + 8U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aIngress, 3U)) + RotL64(aCarry, 11U)) + 0xD1432A6E75B8E858ULL) + aOrbiterAssignSaltC[((aIndex + 62U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aCross, 29U)) + RotL64(aCarry, 51U)) + 0x79BC2F4F76675627ULL;
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 43U)) + 0xBCC2C2BC1B3E10C6ULL) + aNonceWordB;
            aOrbiterF = (aWandererG + RotL64(aIngress, 35U)) + 0xA2438C2E6065CB5AULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0xF0E131D113ECBA72ULL) + aOrbiterUpdateSaltD[((aIndex + 133U)) & S_SALT1];
            aOrbiterB = (((aOrbiterB ^ aOrbiterC) ^ 0xA9A4EEBACCFDA435ULL) ^ aOrbiterUpdateSaltB[((aIndex + 243U)) & S_SALT1]) ^ aNonceWordG;
            aOrbiterB = RotL64((aOrbiterB * 0x91CE1CD461BB51C1ULL), 51U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0x3E8D459A20C652C9ULL) + aNonceWordF;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xCC45C5819DEB0333ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x0FE61C90D2721B6DULL), 43U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x4A1E856ED7B34D01ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x50FDF2F4FB20D464ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8508B20F02E16CA1ULL), 29U);
            //
            aOrbiterK = (((aOrbiterK + aOrbiterC) + 0xBAFDD44BBAA1812EULL) + aOrbiterUpdateSaltF[((aIndex + 75U)) & S_SALT1]) + aNonceWordA;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x8C7B4E9A06D99274ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x2E177AB6D4418DB5ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x6DCAB054FDC3164CULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xFE1A26B926A04CF6ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x781FA5D73E237637ULL), 23U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x858183B3BE0DA549ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x294B36CB1D84D7E0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x22FA50879C25452BULL), 37U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xF995936592D76BA5ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0xE2F1F8C0FEB2FC6EULL) ^ aOrbiterUpdateSaltE[(((255U - aIndex) + 30U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xCDB84D0A8787B635ULL), 3U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterA, 48U);
            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterC);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterF, 57U));
            aIngress = aIngress + RotL64(aOrbiterB, 27U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererG = aWandererG + ((RotL64(aPrevious, 60U) + RotL64(aOrbiterA, 19U)) + aOrbiterK);
            aWandererJ = aWandererJ ^ ((((RotL64(aIngress, 19U) + RotL64(aOrbiterF, 43U)) + aOrbiterK) + aNonceWordH) + aWandererUpdateSaltF[(((255U - aIndex) + 254U)) & S_SALT1]);
            aWandererA = aWandererA + ((((RotL64(aScatter, 29U) + RotL64(aOrbiterB, 36U)) + aOrbiterF) + aNonceWordC) + aWandererUpdateSaltA[((aIndex + 211U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aCross, 3U) + aOrbiterA) + RotL64(aOrbiterC, 11U)) + aNonceWordP);
            aWandererB = aWandererB + (((RotL64(aPrevious, 53U) + RotL64(aOrbiterK, 51U)) + aOrbiterC) + RotL64(aCarry, 53U));
            aWandererD = aWandererD ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterG, 27U)) + aOrbiterJ) + aNonceWordM);
