            aOrbiterG = ((aWandererK + RotL64(aPrevious, 37U)) + RotL64(aCarry, 51U)) + 0xC1E36D5BD3EDA29DULL;
            aOrbiterI = ((aWandererF + RotL64(aIngress, 43U)) + RotL64(aCarry, 27U)) + 0x43E976858599FDAFULL;
            aOrbiterA = ((aWandererJ + RotL64(aPrevious, 11U)) + 0x73A333702834C8C4ULL) + aTwistOrbiterAssignSaltC[((aIndex + 57U)) & S_SALT1];
            aOrbiterB = ((aWandererH + RotL64(aIngress, 3U)) + 0x3B504BA46C245C90ULL) + aTwistOrbiterAssignSaltB[((aIndex + 253U)) & S_SALT1];
