            aOrbiterI = RotL64((aOrbiterI * 0xE53F75840562D619ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x5115AF21CE198341ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0xE3E6FCCC322D9BF0ULL) ^ aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 90U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x23E2A9855CED9A99ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xDDDDC65187DA0EB5ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x1A5AD45C79B2A895ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 86U)) & S_SALT1];
