            //
            aOrbiterK = ((aOrbiterK + aOrbiterB) + 0x7481F7243BB3231DULL) + aTwistOrbiterUpdateSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xD246760F93449F9BULL;
