            //
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 3U) + RotL64(aOrbiterC, 53U)) + aOrbiterG);
            aWandererE = aWandererE + (((RotL64(aIngress, 43U) + aOrbiterG) + RotL64(aOrbiterA, 19U)) + RotL64(aCarry, 29U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 35U) + aOrbiterI) + RotL64(aOrbiterC, 37U));
            aWandererK = aWandererK + ((((RotL64(aCross, 51U) + RotL64(aOrbiterF, 3U)) + aOrbiterG) + RotL64(aCarry, 51U)) + aTwistWandererUpdateSaltD[(((255U - aIndex) + 221U)) & S_SALT1]);
