            //
            aOrbiterK = (aWandererE + RotL64(aScatter, 6U)) + 0x63BF5E093C36F14CULL;
            aOrbiterC = (aWandererB + RotL64(aIngress, 11U)) + 0x0C6623AE02DF8C46ULL;
            aOrbiterA = (aWandererJ + RotL64(aCross, 19U)) + 0x7DB9B7664B5F94EDULL;
            aOrbiterB = ((aWandererC + RotL64(aPrevious, 43U)) + RotL64(aCarry, 41U)) + 0x68ED4FA45F30D488ULL;
