            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x9CD5921A56812E97ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA43ED5326E5BACD3ULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x3CCE622ED399160AULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x4EEF3B4F86D75DC1ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 212U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xC181B5AD94F02C3BULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x3041DB0129CA6372ULL;
