            aOrbiterC = (((aWandererK + RotL64(aIngress, 19U)) + RotL64(aCarry, 27U)) + 0x99D1353DE7108ADFULL) + aTwistOrbiterAssignSaltA[((aIndex + 39U)) & S_SALT1];
